import { apiClient, unwrap, type BffResponse } from '../api';

export interface OpeningWipValueListItem {
  id: string;
  year: number;
  month: number;
  materialCode: string;
  materialName: string;
  accountCode: string;
  expenseAccountCode: string;
  openingQty: number;
  openingAmount: number;
  maVv: string;
  maHd: string;
  maPhi: string;
  maSp: string;
  maKu: string;
  maTtln: string;
  maTtcp: string;
  maBp: string;
  maHs: string;
  maCd: string;
  maTd1: string;
  maTd2: string;
  maTd3: string;
  maTd4: string;
  maTd5: string;
}

export interface OpeningWipValuePage {
  items: OpeningWipValueListItem[];
  totalCount: number;
  page: number;
  pageSize: number;
}

export interface OpeningWipValueWriteBody {
  year: number;
  month: number;
  materialCode: string;
  accountCode: string;
  expenseAccountCode: string;
  openingQty: number;
  openingAmount: number;
  maVv: string;
  maHd: string;
  maPhi: string;
  maSp: string;
  maKu: string;
  maTtln: string;
  maTtcp: string;
  maBp: string;
  maHs: string;
  maCd: string;
  maTd1: string;
  maTd2: string;
  maTd3: string;
  maTd4: string;
  maTd5: string;
}

export interface OpeningWipValueUpdateBody extends OpeningWipValueWriteBody {
  id: string;
}

export async function listOpeningWipValues(query: {
  page: number;
  pageSize: number;
  search?: string;
}): Promise<OpeningWipValuePage> {
  const qs = new URLSearchParams();
  qs.set('page', String(query.page));
  qs.set('pageSize', String(query.pageSize));
  const search = query.search?.trim() ?? '';
  if (search) qs.set('search', search);
  const res = await apiClient.get<BffResponse<OpeningWipValuePage>>(
    `/costing/opening-wip-values?${qs.toString()}`,
  );
  return unwrap(res);
}

export async function createOpeningWipValue(
  body: OpeningWipValueWriteBody,
): Promise<OpeningWipValueListItem> {
  const res = await apiClient.post<BffResponse<OpeningWipValueListItem>>(
    '/costing/opening-wip-values',
    body,
  );
  return unwrap(res);
}

export async function updateOpeningWipValue(
  id: string,
  body: OpeningWipValueUpdateBody,
): Promise<OpeningWipValueListItem> {
  const res = await apiClient.put<BffResponse<OpeningWipValueListItem>>(
    `/costing/opening-wip-values/${encodeURIComponent(id)}`,
    body,
  );
  return unwrap(res);
}

export async function deleteOpeningWipValue(id: string): Promise<boolean> {
  const res = await apiClient.delete<BffResponse<boolean>>(
    `/costing/opening-wip-values/${encodeURIComponent(id)}`,
  );
  return unwrap(res);
}
