import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  Button,
  Input,
  LeaveConfirmModal,
  LinModalFormShell,
  LinPageLayout,
  Modal,
  SearchInput,
  SearchTextInput,
  dispatchAppToast,
  getActiveCompanyCode,
  getAuthUser,
  useCatalogTableBusy,
  useDirtyTracking,
  useFormLeaveGuard,
  type LinListToolbarActionDef,
} from '@linm-soft-org/linm-web-common-components';
import {
  createAccountSearchConfig,
  createMaterialSearchConfig,
  type AccountSearchRecord,
} from '../../../components/search';
import { VoucherListPagination } from '../../../components/list/VoucherListPagination';
import type { MaterialDto } from '../../../services/kt/models';
import {
  createOpeningWipValue,
  deleteOpeningWipValue,
  listOpeningWipValues,
  updateOpeningWipValue,
  type OpeningWipValueListItem,
  type OpeningWipValueWriteBody,
} from '../../../services/gt/openingWipValues';
import { useAppDispatch } from '../../../store/hooks';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import { formatQuantity } from '../../../utils/formatters';
import df from '../../../styles/documentForm.module.css';
import erp from '../../../styles/erpPage.module.css';

const TEST_ID = 'ct-so-du-do-dang';
const PAGE_ID = 'gt-so-du-do-dang-dau-ky';
const TITLE = 'Giá trị sản phẩm dở dang đầu kỳ';
const AMOUNT_RE = /^-?\d{1,16}$|^-?\d{1,16}\.\d{1,4}$/;
const LEAVE_MESSAGE = 'Có thay đổi chưa được lưu. Đóng form sẽ mất dữ liệu đã nhập.';

const DIMS = [
  { key: 'maVv', label: 'Vụ việc', message: 'Nhập vụ việc' },
  { key: 'maHd', label: 'Hợp đồng', message: 'Nhập hợp đồng' },
  { key: 'maPhi', label: 'Khoản mục', message: 'Nhập khoản mục' },
  { key: 'maSp', label: 'Sản phẩm', message: 'Nhập sản phẩm' },
  { key: 'maKu', label: 'Khế ước', message: 'Nhập khế ước' },
  { key: 'maTtln', label: 'Trung tâm lợi nhuận', message: 'Nhập trung tâm lợi nhuận' },
  { key: 'maTtcp', label: 'Trung tâm chi phí', message: 'Nhập trung tâm chi phí' },
  { key: 'maBp', label: 'Bộ phận', message: 'Nhập bộ phận' },
  { key: 'maHs', label: 'Hồ sơ', message: 'Nhập hồ sơ' },
  { key: 'maCd', label: 'Công đoạn', message: 'Nhập công đoạn' },
  { key: 'maTd1', label: 'Mã tự do 1', message: 'Nhập mã tự do 1' },
  { key: 'maTd2', label: 'Mã tự do 2', message: 'Nhập mã tự do 2' },
  { key: 'maTd3', label: 'Mã tự do 3', message: 'Nhập mã tự do 3' },
  { key: 'maTd4', label: 'Mã tự do 4', message: 'Nhập mã tự do 4' },
  { key: 'maTd5', label: 'Mã tự do 5', message: 'Nhập mã tự do 5' },
] as const;

type DimKey = (typeof DIMS)[number]['key'];
type FormMode = 'create' | 'edit';
type SelectionMode = 'keep' | 'clear' | 'prefer';

interface FormState {
  id?: string;
  year: string;
  month: string;
  materialCode: string;
  materialName: string;
  accountCode: string;
  expenseAccountCode: string;
  openingQty: string;
  openingAmount: string;
  maVv: string;
  maHd: string;
  maPhi: string;
  maSp: string;
  maKu: string;
  maTtln: string;
  maTtcp: string;
  maBp: string;
  maHs: string;
  maCd: string;
  maTd1: string;
  maTd2: string;
  maTd3: string;
  maTd4: string;
  maTd5: string;
}

function sessionCompany(): string {
  return (getActiveCompanyCode() ?? getAuthUser()?.companyCode ?? '').trim();
}

function emptyDims(): Pick<FormState, DimKey> {
  return {
    maVv: '',
    maHd: '',
    maPhi: '',
    maSp: '',
    maKu: '',
    maTtln: '',
    maTtcp: '',
    maBp: '',
    maHs: '',
    maCd: '',
    maTd1: '',
    maTd2: '',
    maTd3: '',
    maTd4: '',
    maTd5: '',
  };
}

function emptyForm(): FormState {
  return {
    year: String(new Date().getFullYear()),
    month: '0',
    materialCode: '',
    materialName: '',
    accountCode: '',
    expenseAccountCode: '',
    openingQty: '',
    openingAmount: '',
    ...emptyDims(),
  };
}

function amountToInput(value: number): string {
  if (!Number.isFinite(value)) return '';
  return String(value);
}

function formFromRow(row: OpeningWipValueListItem, keepId: boolean): FormState {
  return {
    id: keepId ? row.id : undefined,
    year: String(row.year),
    month: String(row.month),
    materialCode: row.materialCode,
    materialName: row.materialName,
    accountCode: row.accountCode,
    expenseAccountCode: row.expenseAccountCode,
    openingQty: amountToInput(row.openingQty),
    openingAmount: amountToInput(row.openingAmount),
    maVv: row.maVv ?? '',
    maHd: row.maHd ?? '',
    maPhi: row.maPhi ?? '',
    maSp: row.maSp ?? '',
    maKu: row.maKu ?? '',
    maTtln: row.maTtln ?? '',
    maTtcp: row.maTtcp ?? '',
    maBp: row.maBp ?? '',
    maHs: row.maHs ?? '',
    maCd: row.maCd ?? '',
    maTd1: row.maTd1 ?? '',
    maTd2: row.maTd2 ?? '',
    maTd3: row.maTd3 ?? '',
    maTd4: row.maTd4 ?? '',
    maTd5: row.maTd5 ?? '',
  };
}

function parseWhole(raw: string, min: number, max: number): number | null {
  const text = raw.trim();
  if (!/^\d+$/.test(text)) return null;
  const value = Number(text);
  if (!Number.isInteger(value) || value < min || value > max) return null;
  return value;
}

function parseAmount(raw: string): number | null {
  const text = raw.trim().replace(/\s/g, '').replace(/,/g, '.');
  if (text === '') return 0;
  if (!AMOUNT_RE.test(text)) return null;
  const value = Number(text);
  return Number.isFinite(value) ? value : null;
}

const SoDuDoDangDauKyPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const materialSearch = useMemo(() => createMaterialSearchConfig(), []);
  const accountSearch = useMemo(() => createAccountSearchConfig(), []);
  const expenseAccountSearch = useMemo(() => createAccountSearchConfig(), []);
  const { onDirtyChange, guardedNavigate, leaveConfirmModalProps } = useFormLeaveGuard({
    message: LEAVE_MESSAGE,
  });
  const { markDirty, markClean } = useDirtyTracking(onDirtyChange);

  const [items, setItems] = useState<OpeningWipValueListItem[]>([]);
  const [totalCount, setTotalCount] = useState(0);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(50);
  const [searchDraft, setSearchDraft] = useState('');
  const [searchApplied, setSearchApplied] = useState('');
  const [loading, setLoading] = useState(false);
  const [reloadKey, setReloadKey] = useState(0);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [mode, setMode] = useState<FormMode | null>(null);
  const [form, setForm] = useState<FormState>(emptyForm);
  const [banner, setBanner] = useState('');
  const [saving, setSaving] = useState(false);
  const [deleteOpen, setDeleteOpen] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const selectionMode = useRef<SelectionMode>('keep');
  const preferId = useRef<string | null>(null);

  const { showTableLoading } = useCatalogTableBusy(loading);
  const selected = items.find(row => row.id === selectedId) ?? null;

  useEffect(() => {
    const company = sessionCompany();
    if (!company) {
      setItems([]);
      setTotalCount(0);
      setSelectedId(null);
      dispatchAppToast(dispatch, { message: 'Không xác định đơn vị', type: 'error' });
      return;
    }

    let cancelled = false;
    setLoading(true);
    listOpeningWipValues({
      page,
      pageSize,
      search: searchApplied || undefined,
    })
      .then(data => {
        if (cancelled) return;
        const rows = data.items ?? [];
        setItems(rows);
        setTotalCount(data.totalCount ?? 0);
        setSelectedId(prev => {
          if (selectionMode.current === 'clear') return null;
          if (selectionMode.current === 'prefer') {
            const id = preferId.current;
            if (id && rows.some(row => row.id === id)) return id;
          }
          return prev && rows.some(row => row.id === prev) ? prev : null;
        });
        selectionMode.current = 'keep';
      })
      .catch(err => {
        if (cancelled) return;
        setItems([]);
        setTotalCount(0);
        dispatchAppToast(dispatch, {
          message: getApiErrorMessage(err, 'Không tải được giá trị sản phẩm dở dang đầu kỳ'),
          type: 'error',
        });
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [dispatch, page, pageSize, searchApplied, reloadKey]);

  const touch = (patch: Partial<FormState>) => {
    markDirty();
    setBanner('');
    setForm(prev => ({ ...prev, ...patch }));
  };

  const closeForm = useCallback(() => {
    setMode(null);
    setBanner('');
    markClean();
  }, [markClean]);

  const openCreate = useCallback(() => {
    setForm(emptyForm());
    setBanner('');
    setMode('create');
    markClean();
  }, [markClean]);

  const openEdit = useCallback(() => {
    if (!selected) return;
    setForm(formFromRow(selected, true));
    setBanner('');
    setMode('edit');
    markClean();
  }, [markClean, selected]);

  const openCopy = useCallback(() => {
    if (!selected) return;
    setForm(formFromRow(selected, false));
    setBanner('');
    setMode('create');
    markClean();
  }, [markClean, selected]);

  const validateForm = (): string | null => {
    if (!sessionCompany()) return 'Không xác định đơn vị';
    if (parseWhole(form.year, 1900, 9999) == null) return 'Nhập năm';
    if (parseWhole(form.month, 0, 12) == null) return 'Nhập tháng';
    if (form.accountCode.trim().length > 30) return 'Nhập tài khoản dở dang';
    if (form.expenseAccountCode.trim().length > 30) return 'Nhập tài khoản chi phí';
    if (form.materialCode.trim().length > 30) return 'Nhập mã vật tư';
    for (const dim of DIMS) {
      if (form[dim.key].trim().length > 30) return dim.message;
    }
    if (parseAmount(form.openingQty) == null) return 'Nhập số';
    if (parseAmount(form.openingAmount) == null) return 'Nhập số';
    return null;
  };

  const handleSave = async () => {
    const message = validateForm();
    if (message) {
      setBanner(message);
      return;
    }
    const year = parseWhole(form.year, 1900, 9999);
    const month = parseWhole(form.month, 0, 12);
    const openingQty = parseAmount(form.openingQty);
    const openingAmount = parseAmount(form.openingAmount);
    if (year == null || month == null || openingQty == null || openingAmount == null) return;

    const body: OpeningWipValueWriteBody = {
      year,
      month,
      materialCode: form.materialCode.trim(),
      accountCode: form.accountCode.trim(),
      expenseAccountCode: form.expenseAccountCode.trim(),
      openingQty,
      openingAmount,
      maVv: form.maVv.trim(),
      maHd: form.maHd.trim(),
      maPhi: form.maPhi.trim(),
      maSp: form.maSp.trim(),
      maKu: form.maKu.trim(),
      maTtln: form.maTtln.trim(),
      maTtcp: form.maTtcp.trim(),
      maBp: form.maBp.trim(),
      maHs: form.maHs.trim(),
      maCd: form.maCd.trim(),
      maTd1: form.maTd1.trim(),
      maTd2: form.maTd2.trim(),
      maTd3: form.maTd3.trim(),
      maTd4: form.maTd4.trim(),
      maTd5: form.maTd5.trim(),
    };

    setSaving(true);
    try {
      const saved = mode === 'edit' && form.id
        ? await updateOpeningWipValue(form.id, { ...body, id: form.id })
        : await createOpeningWipValue(body);
      dispatchAppToast(dispatch, { message: 'Đã lưu giá trị sản phẩm dở dang đầu kỳ', type: 'success' });
      selectionMode.current = 'prefer';
      preferId.current = saved?.id ?? null;
      markClean();
      setMode(null);
      setBanner('');
      setReloadKey(key => key + 1);
    } catch (err) {
      dispatchAppToast(dispatch, {
        message: getApiErrorMessage(err, 'Lưu thất bại'),
        type: 'error',
      });
    } finally {
      setSaving(false);
    }
  };

  const confirmDelete = async () => {
    if (!selected) return;
    setDeleting(true);
    try {
      await deleteOpeningWipValue(selected.id);
      dispatchAppToast(dispatch, { message: 'Đã xóa giá trị sản phẩm dở dang đầu kỳ', type: 'success' });
      selectionMode.current = 'clear';
      setSelectedId(null);
      setDeleteOpen(false);
      setReloadKey(key => key + 1);
    } catch (err) {
      setDeleteOpen(false);
      dispatchAppToast(dispatch, {
        message: getApiErrorMessage(err, 'Xóa thất bại'),
        type: 'error',
      });
    } finally {
      setDeleting(false);
    }
  };

  const toolbarActions = useMemo((): LinListToolbarActionDef[] => [
    {
      id: 'refresh',
      placement: 'left',
      action: 'refresh',
      visible: true,
      disabled: loading,
      onClick: () => setReloadKey(key => key + 1),
      testId: `${TEST_ID}-toolbar-refresh-btn`,
    },
    {
      id: 'add',
      placement: 'right',
      action: 'create',
      label: 'Thêm',
      variant: 'primary',
      visible: true,
      onClick: openCreate,
      testId: `${TEST_ID}-toolbar-add-btn`,
    },
    {
      id: 'edit',
      placement: 'right',
      action: 'edit',
      visible: true,
      disabled: !selected || loading,
      onClick: openEdit,
      testId: `${TEST_ID}-toolbar-edit-btn`,
    },
    {
      id: 'copy',
      placement: 'right',
      action: 'copy',
      visible: true,
      disabled: !selected || loading,
      onClick: openCopy,
      testId: `${TEST_ID}-toolbar-copy-btn`,
    },
    {
      id: 'delete',
      placement: 'right',
      action: 'delete',
      visible: true,
      disabled: !selected || loading,
      onClick: () => setDeleteOpen(true),
      testId: `${TEST_ID}-toolbar-delete-btn`,
    },
  ], [loading, openCopy, openCreate, openEdit, selected]);

  const listBody = showTableLoading ? null : items.length === 0 ? (
    <div className={erp.empty} data-testid={`${TEST_ID}-empty`}>
      {searchApplied === ''
        ? 'Không có giá trị sản phẩm dở dang đầu kỳ'
        : 'Không tìm thấy giá trị sản phẩm dở dang đầu kỳ'}
    </div>
  ) : (
    <div className={erp.tableWrapper}>
      <table className={erp.table} data-testid={`${TEST_ID}-grid`}>
        <thead>
          <tr>
            <th>Năm</th>
            <th>Tên vật tư - sản phẩm</th>
            <th>Mã vật tư - sản phẩm</th>
            <th>Tài khoản dở dang</th>
            <th>Tài khoản chi phí</th>
            <th className={erp.colRight}>Số lượng dở dang</th>
            <th className={erp.colRight}>Giá trị dở dang</th>
          </tr>
        </thead>
        <tbody>
          {items.map(row => (
            <tr
              key={row.id}
              data-testid={`${TEST_ID}-row-${row.id}`}
              className={row.id === selectedId ? erp.rowSelected : undefined}
              onClick={() => setSelectedId(row.id)}
            >
              <td>{String(row.year)}</td>
              <td>{row.materialName ? row.materialName : '—'}</td>
              <td>{row.materialCode}</td>
              <td>{row.accountCode}</td>
              <td>{row.expenseAccountCode}</td>
              <td className={erp.colRight}>{formatQuantity(row.openingQty, 4)}</td>
              <td className={erp.colRight}>{formatQuantity(row.openingAmount, 4)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );

  const dimRows = [DIMS.slice(0, 4), DIMS.slice(4, 8), DIMS.slice(8, 12), DIMS.slice(12)];

  return (
    <div className={erp.catalogListRoot} data-testid={`${TEST_ID}-list`}>
      <LinPageLayout
        kind="catalog"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        pageClassName={erp.catalogListPage}
        header={{
          title: TITLE,
          pageId: PAGE_ID,
        }}
        listTitle={TITLE}
        toolbarProps={{
          testIdPrefix: TEST_ID,
          profile: 'catalog',
          actions: toolbarActions,
        }}
        filters={(
          <SearchTextInput
            label="Tìm kiếm"
            value={searchDraft}
            onChange={setSearchDraft}
            onSearch={() => {
              setSearchApplied(searchDraft.trim());
              setPage(1);
            }}
            placeholder="Tìm năm, tháng, vật tư, tên, tài khoản..."
            testId={`${TEST_ID}-search-text`}
          />
        )}
        showTableLoading={showTableLoading}
        skeletonRows={8}
        footer={(
          <VoucherListPagination
            testIdPrefix={TEST_ID}
            page={page}
            totalCount={totalCount}
            pageSize={pageSize}
            onPageChange={setPage}
            onPageSizeChange={size => {
              setPageSize(size);
              setPage(1);
            }}
          />
        )}
        modals={(
          <>
            <LinModalFormShell
              formId={TEST_ID}
              testIdPrefix={TEST_ID}
              size="lg"
              isOpen={mode != null}
              title={mode === 'edit'
                ? 'Sửa giá trị sản phẩm dở dang đầu kỳ'
                : 'Thêm giá trị sản phẩm dở dang đầu kỳ'}
              onClose={() => guardedNavigate(closeForm)}
              footerActions={[
                {
                  id: 'cancel',
                  label: 'Hủy',
                  variant: 'secondary',
                  onClick: () => guardedNavigate(closeForm),
                  testId: `${TEST_ID}-cancel-btn`,
                },
                {
                  id: 'save',
                  label: 'Lưu',
                  variant: 'primary',
                  disabled: saving,
                  onClick: () => { void handleSave(); },
                  testId: `${TEST_ID}-save-btn`,
                },
              ]}
            >
              {banner ? (
                <div className={df.errorBanner} data-testid={`${TEST_ID}-form-error`}>{banner}</div>
              ) : null}
              <div className={df.row4}>
                <div className={df.field}>
                  <label className={df.label} htmlFor={`${TEST_ID}-field-year`}>
                    Năm<span className={df.requiredMark}>*</span>
                  </label>
                  <Input
                    id={`${TEST_ID}-field-year`}
                    data-testid={`${TEST_ID}-field-year`}
                    value={form.year}
                    onChange={e => touch({ year: e.target.value })}
                  />
                </div>
                <div className={df.field}>
                  <label className={df.label} htmlFor={`${TEST_ID}-field-month`}>
                    Tháng<span className={df.requiredMark}>*</span>
                  </label>
                  <Input
                    id={`${TEST_ID}-field-month`}
                    data-testid={`${TEST_ID}-field-month`}
                    value={form.month}
                    onChange={e => touch({ month: e.target.value })}
                  />
                </div>
                <div className={df.field} data-testid={`${TEST_ID}-field-materialCode`}>
                  <span className={df.label}>Mã vật tư - sản phẩm</span>
                  <SearchInput
                    config={materialSearch}
                    value={form.materialCode}
                    primaryDisplay={form.materialCode}
                    showLabel={false}
                    showSecondaryInput={false}
                    placeholder="Mã vật tư - sản phẩm"
                    onChange={(item: MaterialDto) => touch({
                      materialCode: item.code,
                      materialName: item.name,
                    })}
                    onClear={() => touch({ materialCode: '', materialName: '' })}
                  />
                </div>
                <div className={df.field}>
                  <label className={df.label} htmlFor={`${TEST_ID}-field-materialName`}>
                    Tên vật tư - sản phẩm
                  </label>
                  <Input
                    id={`${TEST_ID}-field-materialName`}
                    data-testid={`${TEST_ID}-field-materialName`}
                    value={form.materialName}
                    disabled
                  />
                </div>
              </div>
              <div className={df.row4}>
                <div className={df.field} data-testid={`${TEST_ID}-field-accountCode`}>
                  <span className={df.label}>Tài khoản dở dang</span>
                  <SearchInput
                    config={accountSearch}
                    value={form.accountCode}
                    primaryDisplay={form.accountCode}
                    showLabel={false}
                    showSecondaryInput={false}
                    placeholder="Tài khoản dở dang"
                    onChange={(item: AccountSearchRecord) => touch({ accountCode: item.code })}
                    onClear={() => touch({ accountCode: '' })}
                  />
                </div>
                <div className={df.field} data-testid={`${TEST_ID}-field-expenseAccountCode`}>
                  <span className={df.label}>Tài khoản chi phí</span>
                  <SearchInput
                    config={expenseAccountSearch}
                    value={form.expenseAccountCode}
                    primaryDisplay={form.expenseAccountCode}
                    showLabel={false}
                    showSecondaryInput={false}
                    placeholder="Tài khoản chi phí"
                    onChange={(item: AccountSearchRecord) => touch({ expenseAccountCode: item.code })}
                    onClear={() => touch({ expenseAccountCode: '' })}
                  />
                </div>
                <div className={df.field}>
                  <label className={df.label} htmlFor={`${TEST_ID}-field-openingQty`}>
                    Số lượng dở dang
                  </label>
                  <Input
                    id={`${TEST_ID}-field-openingQty`}
                    data-testid={`${TEST_ID}-field-openingQty`}
                    inputMode="decimal"
                    value={form.openingQty}
                    onChange={e => touch({ openingQty: e.target.value })}
                  />
                </div>
                <div className={df.field}>
                  <label className={df.label} htmlFor={`${TEST_ID}-field-openingAmount`}>
                    Giá trị dở dang
                  </label>
                  <Input
                    id={`${TEST_ID}-field-openingAmount`}
                    data-testid={`${TEST_ID}-field-openingAmount`}
                    inputMode="decimal"
                    value={form.openingAmount}
                    onChange={e => touch({ openingAmount: e.target.value })}
                  />
                </div>
              </div>
              <div className={df.section}>
                <div className={df.sectionTitle}>Phân bổ</div>
                {dimRows.map(row => (
                  <div className={df.row4} key={row[0].key}>
                    {row.map(dim => (
                      <div className={df.field} key={dim.key}>
                        <label className={df.label} htmlFor={`${TEST_ID}-field-${dim.key}`}>
                          {dim.label}
                        </label>
                        <Input
                          id={`${TEST_ID}-field-${dim.key}`}
                          data-testid={`${TEST_ID}-field-${dim.key}`}
                          maxLength={30}
                          value={form[dim.key]}
                          onChange={e => touch({ [dim.key]: e.target.value })}
                        />
                      </div>
                    ))}
                  </div>
                ))}
              </div>
            </LinModalFormShell>
            <Modal
              isOpen={deleteOpen}
              size="sm"
              title="Xóa giá trị sản phẩm dở dang đầu kỳ đã chọn?"
              onClose={() => {
                if (!deleting) setDeleteOpen(false);
              }}
            >
              <div data-testid={`${TEST_ID}-delete-modal`}>
                <p>Xóa giá trị sản phẩm dở dang đầu kỳ đã chọn?</p>
                <Button
                  variant="secondary"
                  data-testid={`${TEST_ID}-delete-cancel-btn`}
                  disabled={deleting}
                  onClick={() => setDeleteOpen(false)}
                >
                  Hủy
                </Button>
                <Button
                  variant="primary"
                  data-testid={`${TEST_ID}-delete-confirm-btn`}
                  disabled={deleting}
                  onClick={() => { void confirmDelete(); }}
                >
                  Xóa
                </Button>
              </div>
            </Modal>
            <LeaveConfirmModal {...leaveConfirmModalProps} />
          </>
        )}
      >
        {listBody}
      </LinPageLayout>
    </div>
  );
};

export default SoDuDoDangDauKyPage;
